import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class StdTypeResolverBuilder_buildTypeSerializer_TriageGen2Test {

    private SerializationConfig config;
    private JavaType baseType;
    private TypeIdResolver idResolver;

    @Before
    public void setUp() {
        config = mock(SerializationConfig.class);
        baseType = mock(JavaType.class);
        idResolver = mock(TypeIdResolver.class);
    }

    @Test
    public void testBuildTypeSerializer_IdNoneReturnsNull() {
        StdTypeResolverBuilder builder = new StdTypeResolverBuilder()
                .init(JsonTypeInfo.Id.NONE, idResolver);

        TypeSerializer result = builder.buildTypeSerializer(config, baseType, Collections.emptyList());
        assertNull("Should return null when Id is NONE", result);
    }














}

